import type { IncomingMessage, ServerResponse } from 'node:http';
import {
  BOOKINGS,
  CASE_BLANK,
  CASE_CLOSED,
  CASE_FULL,
  CRITERIA_HISTORY,
  OPTIONS,
} from '@/test/fixtures/backend-shapes';

// The advisor call-flow routes of the stand-in back end, for the browser tests (W10 to W16, W20, W50).
// The answers are the JSON the real back end's mapping functions write (test/fixtures/backend-shapes.ts,
// generated by backend-shapes.gen.py), so the browser test exercises the shapes the pages will really
// get. The state is one case and one booking per process: the advisor spec runs them in one worker.
// It checks the headers the real routes require (Idempotency-Key on a write, If-Match on a PUT), so a
// page that forgets one fails here as it would against the real back end.

type State = { caseNow: unknown; booking: unknown; acknowledged: number };
const state: State = { caseNow: CASE_BLANK, booking: null, acknowledged: 0 };

function send(response: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}) {
  response
    .writeHead(status, { 'Content-Type': 'application/fhir+json', 'Cache-Control': 'no-store', ...headers })
    .end(JSON.stringify(body));
}

const outcome = (status: number, code: string) =>
  ({ resourceType: 'OperationOutcome', issue: [{ severity: 'error', code }] }) as const;

function drain(request: IncomingMessage): Promise<void> {
  return new Promise((resolve) => {
    request.on('data', () => undefined);
    request.on('end', () => resolve());
  });
}

/** Answers the advisor's `/fhir` routes and returns true; false for any other path. */
export async function handleAdvisorRoute(request: IncomingMessage, response: ServerResponse, pathname: string): Promise<boolean> {
  const method = request.method ?? 'GET';
  const writes = method !== 'GET';
  const isCase = /^\/fhir\/ServiceRequest(\/[^/]+)?(\/\$close)?$/.test(pathname);
  const isTask = /^\/fhir\/Task(\/[^/]+)?(\/\$(cancel|acknowledge))?$/.test(pathname);
  const isOther = pathname === '/fhir/HealthcareService/$filter-options' || pathname === '/fhir/Basic';
  if (!isCase && !isTask && !isOther) return false;
  await drain(request);

  if (writes && request.headers['idempotency-key'] === undefined) {
    send(response, 400, outcome(400, 'invalid'));
    return true;
  }
  if (method === 'PUT' && request.headers['if-match'] === undefined) {
    send(response, 428, outcome(428, 'precondition'));
    return true;
  }

  if (pathname === '/fhir/ServiceRequest' && method === 'POST') {
    state.caseNow = CASE_BLANK;
    state.booking = null;
    send(response, 201, CASE_BLANK, { ETag: 'W/"1"', Location: '/fhir/ServiceRequest/case-1' });
  } else if (/^\/fhir\/ServiceRequest\/[^/]+$/.test(pathname) && method === 'GET') {
    send(response, 200, state.caseNow, { ETag: 'W/"1"' });
  } else if (/^\/fhir\/ServiceRequest\/[^/]+$/.test(pathname) && method === 'PUT') {
    state.caseNow = CASE_FULL;
    send(response, 200, CASE_FULL, { ETag: 'W/"1"' });
  } else if (pathname.endsWith('/$close')) {
    state.caseNow = CASE_CLOSED;
    send(response, 200, CASE_CLOSED);
  } else if (pathname === '/fhir/HealthcareService/$filter-options') {
    send(response, 200, OPTIONS);
  } else if (pathname === '/fhir/Basic') {
    send(response, 200, CRITERIA_HISTORY);
  } else if (pathname === '/fhir/Task' && method === 'POST') {
    state.booking = BOOKINGS.requested;
    send(response, 201, BOOKINGS.requested, { Location: '/fhir/Task/bk-1' });
  } else if (/^\/fhir\/Task\/[^/]+$/.test(pathname) && method === 'GET') {
    if (state.booking === null) send(response, 404, outcome(404, 'not-found'));
    else send(response, 200, state.booking);
  } else if (pathname.endsWith('/$acknowledge')) {
    state.acknowledged += 1;
    send(response, 200, { resourceType: 'Parameters', parameter: [{ name: 'acknowledged', valueBoolean: true }] });
  } else {
    send(response, 404, outcome(404, 'not-found'));
  }
  return true;
}
